/*
 * A040513  Continued fraction for sqrt(537).
 * https://oeis.org/A040513
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, easy, less
 * Formula:   Continued fraction terms of sqrt(537); a(0) = ⌊√537⌋, for n>0,
 *            a(n) are generated by the standard recurrence: m_{k+1} = d_k *
 *            a_k - m_k d_{k+1} = (D - m_{k+1}^2) / d_k a_{k+1} = ⌊(a0 +
 *            m_{k+1}) / d_{k+1}⌋ The sequence repeats after a_k = 2*a0
 *            (period ends)
 * Range:     u8 none, u16 n <= 89, u32 n <= 89, u64 n <= 89, u128 n <= 89,
 *            big any n
 * Validated: partial, pass, 90 terms through n = 89 (2026-11-01)
 * Helpers:   ipow_i32
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include "../utils/ipow_i32.h"

/* Floor square root by binary search */
static inline seq_t floor_sqrt(seq_t x)
{
    seq_t lo = 0, hi = 1;
    while (ipow_i32(hi, 2) <= x)
        hi <<= 1;
    while (lo < hi)
    {
        seq_t mid = (lo + hi) >> 1;
        seq_t mid2 = mid * mid;
        if (mid2 <= x)
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo - 1;
}

/* static storage for the periodic part of the continued fraction */
#define MAX_PERIOD 256

seq_t a(idx_t n) {
    static bool initialized = false;
    static seq_t period[MAX_PERIOD];
    static size_t period_len = 0;

    if (!initialized) {
        const seq_t D = (seq_t)537;
        const seq_t a0 = floor_sqrt(D);

        seq_t m = (seq_t)0;
        seq_t d = (seq_t)1;
        seq_t a_prev = a0;

        size_t i = 0;
        while (true) {
            /* next terms of the continued fraction */
            const seq_t m_next = d * a_prev - m;
            const seq_t d_next = (D - m_next * m_next) / d;
            const seq_t a_next = (a0 + m_next) / d_next;

            if (i >= MAX_PERIOD) {
                /* safety guard: period too long for the static array */
                break;
            }
            period[i++] = a_next;

            /* update for next iteration */
            m = m_next;
            d = d_next;
            a_prev = a_next;

            /* period ends when a_next equals 2*a0 */
            if (a_next == ((seq_t)2 * a0)) {
                break;
            }
        }

        period_len = i;
        initialized = true;
    }

    if (n == (idx_t)0) {
        /* first term is the integer part of sqrt(537) */
        return floor_sqrt((seq_t)537);
    } else {
        /* periodic part repeats */
        size_t idx = (size_t)(n - (idx_t)1) % period_len;
        return period[idx];
    }
}
